from collections import deque

def gp(n,k):
    edges=set()
    # outer i, inner n+i
    for i in range(n):
        for a,b in [(i,(i+1)%n),(i,n+i),(n+i,n+((i+k)%n))]:
            if a>b:a,b=b,a
            edges.add((a,b))
    return edges

def girth(N,edges):
